"""Premium single-page web experience for FLOP Nexus.

The UI deliberately keeps protocol details behind progressive disclosure. It is a
server-rendered, dependency-free shell so the FastAPI deployment remains simple.
Live metrics are never fabricated; the dashboard starts in an honest demo state
until a verified data source is connected.
"""

from __future__ import annotations

from html import escape


